// Count KEY0 presses on the LEDs; hold KEY1 for a second to clear.
module top #(
  parameter CLK_HZ = 50_000_000
) (
  input        MAX10_CLK1_50,
  input  [1:0] KEY,     // 0 while pressed, debounced on the board
  output [9:0] LEDR
);
  // 1. Synchronise: two flip-flops bring each key onto our clock.
  reg [1:0] k0 = 2'b11;
  reg [1:0] k1 = 2'b11;
  always @(posedge MAX10_CLK1_50) begin
    k0 <= {k0[0], KEY[0]};
    k1 <= {k1[0], KEY[1]};
  end

  // 2. Edge: a pulse one clock long when KEY0 goes from 1 to 0.
  wire press = k0[1] & ~k0[0];

  // 3. Hold: count cycles while KEY1 is down; a full second clears.
  localparam HOLD = CLK_HZ;
  reg [31:0] held = 0;
  always @(posedge MAX10_CLK1_50) begin
    if (k1[1])
      held <= 0;
    else if (held != HOLD)
      held <= held + 1;
  end
  wire clear = (held == HOLD - 1);

  // 4. Count the presses; a clear wins.
  reg [9:0] count = 0;
  always @(posedge MAX10_CLK1_50) begin
    if (clear)
      count <= 0;
    else if (press)
      count <= count + 1;
  end

  assign LEDR = count;
endmodule

